package org.junit.antora;

import org.zeroturnaround.exec.ProcessExecutor;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.UnaryOperator;
import java.util.regex.Pattern;
import java.util.stream.IntStream;

import static java.nio.file.StandardOpenOption.APPEND;
import static java.util.stream.Collectors.joining;
import static java.util.stream.Collectors.toCollection;

public class Migrator {

    static void main(String[] args) throws Exception {
        if (args.length != 1) {
            throw new IllegalArgumentException("Should be called with exactly 1 argument, but was:\n" + Arrays.toString(args));
        }

        var projectDir = Path.of(args[0]);
        new Migrator(projectDir).run();
    }

    private final Path projectDir;
    private final Path asciidocSrcDir;
    private final Path pagesDir;
    private final Path partialsDir;
    private final Path navFile;

    private int counter;

    public Migrator(Path projectDir) throws IOException {
        this.projectDir = projectDir.toAbsolutePath().normalize();

        asciidocSrcDir = this.projectDir.resolve("documentation/src/docs/asciidoc");
        var antoraModuleDir = this.projectDir.resolve("documentation/modules/ROOT");
        pagesDir = Files.createDirectories(antoraModuleDir.resolve("pages"));
        partialsDir = Files.createDirectories(antoraModuleDir.resolve("partials"));
        navFile = antoraModuleDir.resolve("nav.adoc");
    }

    private void run() throws Exception {

        exec("git", "switch", "-c", "antora-migrator-tmp");

        // TODO migrate link-attributes.adoc to antora.yml

        removeUserGuideMainDocument();
        migrateOverview();
        migrateReleaseNotes();

        // TODO fix all links
    }

    private void removeUserGuideMainDocument() throws Exception {
        gitRemoveSingleFile(asciidocSrcDir.resolve("user-guide/index.adoc"), "Asciidoctor User Guide main document");
    }

    private void migrateOverview() throws Exception {
        var overviewFile = pagesDir.resolve("overview.adoc");
        migrate(asciidocSrcDir.resolve("user-guide/overview.adoc"), overviewFile, doc -> {
            doc.reduceHeadingLevel();
            doc.removeTopLevelAnchor();
            doc.addAttribute("page-aliases", "index.adoc");
        });
        addPageToNavFile(overviewFile);
    }

    private void migrateReleaseNotes() throws Exception {

        var releaseNotesFile = pagesDir.resolve("release-notes.adoc");
        migrate(asciidocSrcDir.resolve("release-notes/index.adoc"), releaseNotesFile, doc -> {
            doc.removeTopLevelAnchor();
            doc.removeAuthors();
            doc.changeTitle("Release Notes");
            doc.removeAttributes("docinfodir", "docinfo2", "numbered!", "last-update-label!");
            doc.changeAttribute("basedir", "partial$release-notes");
            doc.replace("include::{includedir}/link-attributes.adoc[]\n\n", "");
        });
        addPageToNavFile(releaseNotesFile);

        var asciidocReleaseNotesDir = asciidocSrcDir.resolve("release-notes");
        var releaseNotesPartialsDir = Files.createDirectories(partialsDir.resolve("release-notes"));
        try (var listing = Files.list(asciidocReleaseNotesDir)) {
            listing.filter(file -> file.getFileName().toString().matches("release-notes-\\d.+\\.adoc"))
                    .forEach(file -> moveToAntora(file, releaseNotesPartialsDir.resolve(file.getFileName())));
        }

        migrate(asciidocReleaseNotesDir.resolve("release-notes-TEMPLATE.adoc"), releaseNotesPartialsDir.resolve("release-notes-TEMPLATE.adoc"), doc ->
                doc.replace("'include:' this new file in index.adoc", "'include:' this new file in " + releaseNotesPartialsDir.relativize(releaseNotesFile)));
    }

    private void addPageToNavFile(Path page) throws Exception {
        var relativePath = pagesDir.relativize(page);
        Files.write(navFile, List.of("%s xref:%s[]".formatted(repeat(relativePath.getNameCount(), "*"), relativePath)), APPEND);
        gitCommitSingleFile(navFile, "Add %s to navigation".formatted(relativePath));
    }

    private void migrate(Path source, Path target, Consumer<Document> consumer) {
        try {
            moveToAntora(source, target);
            if (consumer != null) {
                var document = new Document(Files.readString(target));
                consumer.accept(document);
                Files.writeString(target, document.text);
                gitCommitSingleFile(target, "Migrate %s to Antora syntax".formatted(target.getFileName()));
            }
        } catch (Exception e) {
            throw new RuntimeException("Failed to migrate " + source, e);
        }
    }

    private void moveToAntora(Path source, Path target) {
        try {
            exec("git", "mv", source, target);
            gitCommitSingleFile(target, "Move %s to Antora module".formatted(target.getFileName()));
        } catch (Exception e) {
            throw new RuntimeException("Failed to move " + source, e);
        }
    }

    private void gitCommitSingleFile(Path file, String message) throws Exception {
        exec("git", "add", file);
        gitCommit(message);
    }

    private void gitRemoveSingleFile(Path file, String name) throws Exception {
        exec("git", "rm", file);
        gitCommit("Remove " + name);
    }

    private void gitCommit(String message) throws Exception {
        exec("git", "commit", "-m", message);
    }

    private void exec(Object... command) throws Exception {
        var commandStrings = Arrays.stream(command).map(String::valueOf).toList();
        System.out.printf("[%d] Executing: %s%n", ++counter, String.join(" ", commandStrings));
        var exitValue = new ProcessExecutor()
                .command(commandStrings)
                .directory(projectDir.toFile())
                .redirectOutput(System.out)
                .redirectError(System.out)
                .execute()
                .getExitValue();
        System.out.println();
        if (exitValue != 0) {
            throw new RuntimeException("Command failed with exit code %d: %s".formatted(exitValue, Arrays.toString(command)));
        }
    }

    private static String repeat(int times, String value) {
        return IntStream.range(0, times).mapToObj(__ -> value).collect(joining());
    }

    private static class Document {

        private static final Pattern HEADING_PATTERN = Pattern.compile("^(=+)= ");

        String text;

        Document(String text) {
            this.text = text;
        }

        void removeTopLevelAnchor() {
            text = text.replaceFirst("^\\[\\[.+]]\\s*", "");
        }

        void removeAuthors() {
            transformLines(lines -> {
                lines.remove(1);
                return lines;
            });
        }

        void changeTitle(String title) {
            text = text.replaceFirst("^= .*\n", "= %s\n".formatted(title));
        }

        void removeAttributes(String... attributeNames) {
            transformLines(lines -> lines.stream()
                    .filter(line -> Arrays.stream(attributeNames)
                            .noneMatch(attributeName -> line.startsWith(toAttributeDefinition(attributeName))))
                    .toList());
        }

        void changeAttribute(String attributeName, String value) {
            var attributeDefinition = toAttributeDefinition(attributeName);
            transformLines(lines -> lines.stream()
                    .map(line -> {
                        if (line.startsWith(attributeDefinition)) {
                            return attributeDefinition + " " + value;
                        }
                        return line;
                    })
                    .toList());
        }

        void addAttribute(String attributeName, String value) {
            transformLines(lines -> {
                lines.add(1, toAttributeDefinition(attributeName) + " " + value);
                return lines;
            });
        }

        void replace(String from, String to) {
            text = text.replace(from, to);
        }

        void reduceHeadingLevel() {
            transformLines(lines -> lines.stream()
                    .map(line -> HEADING_PATTERN.matcher(line).replaceFirst("$1 "))
                    .toList());
        }

        private void transformLines(UnaryOperator<List<String>> transformer) {
            List<String> lines = text.lines().collect(toCollection(ArrayList::new));
            lines = transformer.apply(lines);
            text = String.join("\n", lines);
            if (!text.endsWith("\n")) {
                text += "\n";
            }
        }

        private static String toAttributeDefinition(String attributeName) {
            return ":%s:".formatted(attributeName);
        }
    }
}
